import React, { useState } from 'react';
import { NavLink, useLocation } from 'react-router-dom';
import {
  Cpu,
  LayoutDashboard,
  Factory,
  Server,
  Radio,
  Sparkles,
  FlaskConical,
  Wrench,
  BarChart3,
  AlertTriangle,
  FileText,
  Settings,
  ChevronLeft,
  ChevronRight,
  Search,
  Activity,
  CheckCircle2,
} from 'lucide-react';

const Sidebar = () => {
  const location = useLocation();
  const [collapsed, setCollapsed] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // Primary Navigation Items with Dedicated Professional Module Indicators
  const navItems = [
    { key: 'dashboard', title: 'Dashboard', icon: LayoutDashboard, path: '/', badge: 'Live', color: '#2563EB' },
    { key: 'factoryOverview', title: 'Factory Overview', icon: Factory, path: '/plants', badge: '6 Plants', color: '#0284C7' },
    { key: 'digitalTwin', title: 'Digital Twin', icon: Cpu, path: '/digital-twin', badge: '3D Sync', color: '#06B6D4' },
    { key: 'assetInventory', title: 'Asset Inventory', icon: Server, path: '/assets', badge: '20 Looms', color: '#0EA5E9' },
    { key: 'sensorMonitoring', title: 'Sensor Monitoring', icon: Radio, path: '/sensors', badge: '136 Feeds', color: '#06B6D4' },
    { key: 'aiIntelligence', title: 'AI Intelligence', icon: Sparkles, path: '/ai-intelligence', badge: '99.4%', color: '#8B5CF6' },
    { key: 'whatIfSimulator', title: 'What-If Simulator', icon: FlaskConical, path: '/what-if', badge: 'AI Lab', color: '#F59E0B' },
    { key: 'maintenanceCenter', title: 'Maintenance Center', icon: Wrench, path: '/maintenance', badge: '3 Orders', color: '#F97316' },
    { key: 'analytics', title: 'Analytics', icon: BarChart3, path: '/analytics', badge: '96.4% OEE', color: '#4F46E5' },
    { key: 'alerts', title: 'Alerts', icon: AlertTriangle, path: '/alerts', badge: '3 Active', color: '#EF4444' },
    { key: 'reports', title: 'Reports', icon: FileText, path: '/reports', color: '#10B981' },
    { key: 'settings', title: 'Settings', icon: Settings, path: '/settings', color: '#64748B' },
  ];

  const filteredItems = navItems.filter((item) =>
    item.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <aside className={`sidebar ${collapsed ? 'collapsed' : ''}`}>
      {/* Sidebar Header Brand Logo */}
      <div className="sidebar-brand">
        <div className="brand-icon-box" style={{ background: '#2563EB' }}>
          <Cpu size={22} />
        </div>
        {!collapsed && (
          <div className="brand-text-group">
            <span className="brand-title">TexTwin</span>
            <span className="brand-badge">Digital Twin OS</span>
          </div>
        )}
      </div>

      {/* Search Bar Input */}
      {!collapsed && (
        <div className="sidebar-search-box">
          <Search size={14} className="sidebar-search-icon" />
          <input
            type="text"
            className="sidebar-search-input"
            placeholder="Search navigation..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      )}

      {/* Navigation List */}
      <nav className="sidebar-nav">
        {filteredItems.map((item) => {
          const Icon = item.icon;
          const isItemActive = location.pathname === item.path;

          return (
            <NavLink
              key={item.key}
              to={item.path}
              className={() => `sidebar-link ${isItemActive ? 'active' : ''}`}
              title={item.title}
              end={item.path === '/'}
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: '0.65rem',
                borderLeft: isItemActive ? `4px solid ${item.color}` : '4px solid transparent',
                background: isItemActive ? `${item.color}15` : 'transparent',
              }}
            >
              <Icon size={20} style={{ flexShrink: 0, minWidth: '20px', color: isItemActive ? item.color : 'inherit' }} />
              {!collapsed && (
                <div style={{ flex: 1, display: 'flex', justifyContent: 'space-between', alignItems: 'center', overflow: 'hidden' }}>
                  <span className="sidebar-link-text" style={{ whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', fontWeight: isItemActive ? '800' : '700', color: isItemActive ? item.color : 'inherit' }}>
                    {item.title}
                  </span>
                  {item.badge && (
                    <span
                      className="sidebar-mini-badge"
                      style={{
                        flexShrink: 0,
                        marginLeft: '6px',
                        whiteSpace: 'nowrap',
                        background: isItemActive ? item.color : '#E2E8F0',
                        color: isItemActive ? '#ffffff' : '#475569',
                        fontWeight: '800',
                      }}
                    >
                      {item.badge}
                    </span>
                  )}
                </div>
              )}
            </NavLink>
          );
        })}
      </nav>

      {/* Professional Enterprise System Status Panel */}
      {!collapsed && (
        <div
          className="sidebar-status-box"
          style={{
            background: '#F8FAFC',
            border: '1px solid #E2E8F0',
            borderRadius: '10px',
            padding: '0.85rem 1rem',
            margin: '0.75rem',
            boxShadow: '0 2px 8px rgba(0, 0, 0, 0.02)',
          }}
        >
          <div
            style={{
              fontSize: '0.72rem',
              fontWeight: '800',
              color: '#1E293B',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'space-between',
              marginBottom: '0.65rem',
              paddingBottom: '0.4rem',
              borderBottom: '1px solid #E2E8F0',
              letterSpacing: '0.4px',
            }}
          >
            <span style={{ display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
              <Activity size={14} style={{ color: '#2563EB' }} /> SYSTEM HEALTH
            </span>
            <span style={{ fontSize: '0.68rem', color: '#059669', fontWeight: '800', display: 'flex', alignItems: 'center', gap: '0.2rem' }}>
              <CheckCircle2 size={12} /> 100% Operational
            </span>
          </div>

          <div style={{ display: 'flex', flexDirection: 'column', gap: '0.4rem', fontSize: '0.74rem' }}>

            {/* MySQL DB */}
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
